import { Client, ServiceOrder, Part, Product, CashTransaction } from '../types';

/**
 * Esse arquivo contém os esqueletos das funções de integração.
 * Em um cenário real, você substituiria os retornos estáticos por chamadas fetch() para seu servidor.
 */

const API_DELAY = 500;

export const api = {
  // Clients
  getClients: async (): Promise<Client[]> => {
    return new Promise((resolve) => {
      setTimeout(() => resolve([]), API_DELAY);
    });
  },
  createClient: async (client: Omit<Client, 'id' | 'createdAt'>): Promise<Client> => {
    return new Promise((resolve) => {
      setTimeout(() => resolve({ ...client, id: Math.random().toString(36).substr(2, 9), createdAt: new Date().toISOString() }), API_DELAY);
    });
  },

  // Service Orders
  getServiceOrders: async (): Promise<ServiceOrder[]> => {
    return new Promise((resolve) => {
      setTimeout(() => resolve([]), API_DELAY);
    });
  },
  createServiceOrder: async (os: Omit<ServiceOrder, 'id' | 'osNumber' | 'openedAt'>): Promise<ServiceOrder> => {
    return new Promise((resolve) => {
      setTimeout(() => resolve({ 
        ...os, 
        id: Math.random().toString(36).substr(2, 9), 
        osNumber: Math.floor(1000 + Math.random() * 9000).toString(),
        openedAt: new Date().toISOString() 
      }), API_DELAY);
    });
  },

  // Stock
  getParts: async (): Promise<Part[]> => {
    return new Promise((resolve) => {
      setTimeout(() => resolve([]), API_DELAY);
    });
  },

  // Products
  getProducts: async (): Promise<Product[]> => {
    return new Promise((resolve) => {
      setTimeout(() => resolve([]), API_DELAY);
    });
  },

  // Cash
  getTransactions: async (): Promise<CashTransaction[]> => {
    return new Promise((resolve) => {
      setTimeout(() => resolve([]), API_DELAY);
    });
  }
};

