export default Layout;

import React, { useState } from 'react';
import Layout from './components/Layout';
import Dashboard from './views/Dashboard';
import ClientsView from './views/ClientsView';
import ServiceOrdersList from './views/ServiceOrdersList';
import ServiceOrderForm from './views/ServiceOrderForm';
import InventoryView from './views/InventoryView';
import CashView from './views/CashView';

const App: React.FC = () => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isCreatingOS, setIsCreatingOS] = useState(false);

  const handleNewOS = () => {
    setActiveTab('os');
    setIsCreatingOS(true);
  };

  const handleSaveOS = (data: any) => {
    console.log("Salvando OS no Backend:", data);
    alert("Ordem de Serviço salva com sucesso (Simulação)!");
    setIsCreatingOS(false);
  };

  const renderContent = () => {
    if (activeTab === 'dashboard') {
      return (
        <Dashboard 
          onNewOS={handleNewOS} 
          onViewAllOS={() => setActiveTab('os')} 
        />
      );
    }

    if (activeTab === 'os') {
      if (isCreatingOS) {
        return <ServiceOrderForm onBack={() => setIsCreatingOS(false)} onSave={handleSaveOS} />;
      }
      return <ServiceOrdersList onNewOS={() => setIsCreatingOS(true)} />;
    }

    if (activeTab === 'clientes') {
      return <ClientsView />;
    }

    if (activeTab === 'estoque' || activeTab === 'produtos') {
      return <InventoryView />;
    }

    if (activeTab === 'caixa') {
      return <CashView />;
    }

    return (
      <div className="flex flex-col items-center justify-center h-64 text-slate-400">
        <h2 className="text-xl font-bold italic">Seção em Desenvolvimento</h2>
        <p>Estamos trabalhando para trazer essa funcionalidade em breve.</p>
      </div>
    );
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={(tab) => {
      setActiveTab(tab);
      setIsCreatingOS(false); // Reset OS form when switching tabs
    }}>
      {renderContent()}
    </Layout>
  );
};

export default App;

