                  <select 
                    value={newModel.brand}
                    onChange={e => setNewModel({...newModel, brand: e.target.value})}
                    className="w-full p-4 bg-white border border-slate-200 rounded-2xl font-bold focus:ring-2 focus:ring-blue-500 outline-none shadow-sm"
