            className="flex items-center gap-2 bg-blue-600 text-white px-6 py-2 rounded-lg font-semibold hover:bg-blue-700 shadow-md shadow-blue-200 transition-all active:scale-95"
          >
            <Save size={18} />
            Salvar {formData.type === OSType.ORCAMENTO ? 'Orçamento' : 'OS'}
