interface ServiceOrderFormProps {
  onBack: () => void;
  onSave: (data: any) => void;
}

const ServiceOrderForm: React.FC<ServiceOrderFormProps> = ({ onBack, onSave }) => {
  const [formData, setFormData] = useState({
    type: OSType.REPARO,
    originalOsNumber: '',
    clientId: '',
    clientName: '',
    brand: 'Samsung',
    model: '',
    color: '',
    capacity: '128GB',
    imei: '',
    imei2: '',
    password: '',
    itemsLeft: [] as string[],
    physicalCondition: [] as string[],
    problemReported: '',
    technicalDiagnosis: '',
    servicesToExecute: '',
    parts: [] as any[],
    laborValue: 0,
    shippingValue: 0,
    discount: 0,
    downPayment: 0,
    paymentMethod: 'Pix',
    technicalResponsible: '',
    status: OSStatus.RECEBIDO,
    deliveryForecast: '',
    internalNotes: '',
    termsAccepted: false
  });

  const [partsTotal, setPartsTotal] = useState(0);

  useEffect(() => {
    const total = formData.parts.reduce((acc, p) => acc + (p.quantity * p.unitPrice), 0);
    setPartsTotal(total);
  }, [formData.parts]);

  const totalOS = partsTotal + formData.laborValue + formData.shippingValue - formData.discount;

  const handleToggleItem = (item: string) => {
    setFormData(prev => ({
      ...prev,
      itemsLeft: prev.itemsLeft.includes(item) 
        ? prev.itemsLeft.filter(i => i !== item)
        : [...prev.itemsLeft, item]
    }));
  };

  const handleToggleCondition = (condition: string) => {
    setFormData(prev => ({
      ...prev,
      physicalCondition: prev.physicalCondition.includes(condition) 
        ? prev.physicalCondition.filter(c => c !== condition)
        : [...prev.physicalCondition, condition]
    }));
  };

  const addPart = () => {
    setFormData(prev => ({
      ...prev,
      parts: [...prev.parts, { id: Date.now(), name: '', quantity: 1, unitPrice: 0 }]
    }));
  };

  const removePart = (id: number) => {
    setFormData(prev => ({
      ...prev,
      parts: prev.parts.filter(p => p.id !== id)
    }));
  };

  const updatePart = (id: number, field: string, value: any) => {
    setFormData(prev => ({
      ...prev,
      parts: prev.parts.map(p => p.id === id ? { ...p, [field]: value } : p)
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.clientName || !formData.model || !formData.imei) {
      alert("Por favor, preencha os campos obrigatórios: Cliente, Aparelho e IMEI.");
      return;
    }
    if (formData.type === OSType.GARANTIA && !formData.originalOsNumber) {
      alert("Para garantias, é obrigatório informar o número da OS original.");
      return;
    }
    if (!formData.termsAccepted) {
      alert("O cliente precisa aceitar os termos de responsabilidade.");
      return;
    }
    onSave(formData);
  };

  return (
    <div className="max-w-5xl mx-auto pb-20 animate-in slide-in-from-right duration-300">
