              <div className="flex justify-between text-slate-500 font-bold uppercase text-[10px] tracking-widest">
                <span>Total Peças:</span>
                <span className="text-white text-base">R$ {partsTotal.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-slate-500 font-bold uppercase text-[10px] tracking-widest">
                <span>Serviços:</span>
                <span className="text-white text-base">R$ {formData.laborValue.toFixed(2)}</span>
              </div>
              <div className="flex justify-between text-rose-500/80 font-bold uppercase text-[10px] tracking-widest">
                <span>Desconto:</span>
                <span className="text-rose-400 text-base">- R$ {formData.discount.toFixed(2)}</span>
