              <div className="border-t border-white/10 pt-6 mt-4 flex justify-between text-4xl font-black text-white tracking-tighter">
                <span className="text-[10px] text-slate-600 font-black uppercase tracking-[0.4em] mt-3">TOTAL</span>
                <span>R$ {totalOS.toFixed(2)}</span>
