              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1 tracking-widest">Situação Operacional</label>
                <select 
                  value={formData.status}
                  onChange={(e) => setFormData({...formData, status: e.target.value as OSStatus})}
                  className="w-full p-4 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none shadow-sm font-black text-slate-700"
                >
                  {Object.values(OSStatus).map(s => <option key={s} value={s}>{s}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1 tracking-widest">
                  {formData.type === OSType.ORCAMENTO ? 'Validade da Proposta' : 'Compromisso de Entrega'}
                </label>
                <input 
                  type="datetime-local" 
                  value={formData.deliveryForecast}
                  onChange={(e) => setFormData({...formData, deliveryForecast: e.target.value})}
                  className="w-full p-4 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none shadow-sm font-black text-slate-700 uppercase" 
                />
              </div>
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1 tracking-widest">Método de Liquidação</label>
                <select 
                  value={formData.paymentMethod}
                  onChange={(e) => setFormData({...formData, paymentMethod: e.target.value})}
                  className="w-full p-4 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none shadow-sm font-black text-slate-700"
                >
                  {PAYMENT_METHODS.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
            </div>
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1 tracking-widest">Notas de Laboratório (Interno)</label>
              <textarea 
                rows={3} 
                value={formData.internalNotes}
                onChange={(e) => setFormData({...formData, internalNotes: e.target.value})}
                className="w-full p-4 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none resize-none shadow-sm font-bold text-slate-700 italic"
                placeholder="Observações críticas para o técnico..."
              />
            </div>
          </div>
        </div>

        {/* Seção 5: Garantia Legal */}
        <div className="bg-white p-10 rounded-[3rem] border border-slate-100 shadow-sm">
          <h2 className="font-black text-slate-800 mb-8 flex items-center gap-4 uppercase text-xs tracking-[0.2em]">
             <div className="w-2 h-8 bg-blue-600 rounded-full"></div>
             Termo de Autorização e Garantia
          </h2>
          <div className="bg-slate-50/80 p-8 rounded-[2rem] border border-slate-100 text-[11px] text-slate-500 leading-loose h-48 overflow-y-auto mb-8 font-mono shadow-inner">
            <p className="mb-4"><span className="font-black text-slate-800 uppercase tracking-widest">01. Cobertura:</span> 90 dias de garantia conforme CDC, exclusiva para defeitos de fabricação na peça substituída.</p>
            <p className="mb-4"><span className="font-black text-slate-800 uppercase tracking-widest">02. Validade:</span> Orçamentos são propostas válidas por 05 dias corridos.</p>
            <p className="mb-4"><span className="font-black text-slate-800 uppercase tracking-widest">03. Retirada:</span> Aparelhos não reclamados em 90 dias após aviso de 'Pronto' entram em processo de leilão para quitação de custos.</p>
            <p className="mb-4"><span className="font-black text-slate-800 uppercase tracking-widest">04. Dados:</span> O cliente declara ter feito backup. Não nos responsabilizamos por mídias e arquivos.</p>
            <p><span className="font-black text-slate-800 uppercase tracking-widest">05. Oxidação:</span> Aparelhos com histórico de contato com líquidos não possuem garantia em circuitos secundários.</p>
          </div>
          <label className="flex items-center gap-6 cursor-pointer group p-6 border-2 border-slate-50 rounded-[2.5rem] hover:bg-blue-50/30 transition-all border-dashed">
            <input 
              type="checkbox" 
              checked={formData.termsAccepted}
              onChange={(e) => setFormData({...formData, termsAccepted: e.target.checked})}
              className="w-8 h-8 rounded-xl border-slate-300 text-blue-600 focus:ring-blue-500 transition-all shadow-sm"
            />
            <div className="flex flex-col">
              <span className="text-base font-black text-slate-800 group-hover:text-blue-600 transition-colors uppercase tracking-tight">O Cliente confirma a veracidade das informações e autoriza o reparo.</span>
              <span className="text-xs text-slate-400 font-bold uppercase tracking-widest">A ciência dos termos é obrigatória para salvar a OS.</span>
            </div>
          </label>
        </div>

        <div className="flex flex-col sm:flex-row gap-6 pt-10 border-t border-slate-100">
          <button 
            type="submit"
            className="flex-1 bg-blue-600 text-white py-8 rounded-[2.5rem] font-black text-2xl hover:bg-blue-700 shadow-2xl shadow-blue-200 transition-all flex items-center justify-center gap-6 active:scale-[0.98] uppercase tracking-[0.2em]"
          >
            <Save size={32} />
            FINALIZAR {formData.type === OSType.ORCAMENTO ? 'ORÇAMENTO' : 'ORDEM DE SERVIÇO'}
          </button>
        </div>
      </form>
    </div>
  );
};

