{
  "name": "Painel da Assistência",
  "description": "Sistema completo de gestão para assistência técnica de celulares, incluindo dashboard, ordens de serviço, cadastro de clientes, estoque e vendas rápidas.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React, { useState, useEffect, useRef } from 'react';
import { 
  ArrowLeft, 
  Save, 
  Plus, 
  UserPlus, 
  Search, 
  Trash2,
  Package,
  FileSearch,
  AlertTriangle,
  Truck,
  ShieldCheck,
  Smartphone,
  Zap,
  Camera,
  Printer,
  X,
  Sparkles
} from 'lucide-react';
import { OS_BRANDS, STORAGE_CAPACITIES, PAYMENT_METHODS } from '../constants';
import { OSStatus, OSType } from '../types';
import { GoogleGenAI } from "@google/genai";

interface ServiceOrderFormProps {
  onBack: () => void;
  onSave: (data: any) => void;
}

const ServiceOrderForm: React.FC<ServiceOrderFormProps> = ({ onBack, onSave }) => {
  const [formData, setFormData] = useState({
    type: OSType.REPARO,
    originalOsNumber: '',
    clientId: '',
    clientName: '',
    brand: 'Samsung',
    model: '',
    color: '',
    capacity: '128GB',
    imei: '',
    imei2: '',
    password: '',
    itemsLeft: [] as string[],
    physicalCondition: [] as string[],
    photos: [] as string[],
    problemReported: '',
    technicalDiagnosis: '',
    servicesToExecute: '',
    parts: [] as any[],
    laborValue: 0,
    shippingValue: 0,
    discount: 0,
    downPayment: 0,
    paymentMethod: 'Pix',
    technicalResponsible: '',
    status: OSStatus.RECEBIDO,
    deliveryForecast: '',
    internalNotes: '',
    termsAccepted: false
  });

  const [partsTotal, setPartsTotal] = useState(0);
  const [isCameraOpen, setIsCameraOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const total = formData.parts.reduce((acc, p) => acc + (p.quantity * p.unitPrice), 0);
    setPartsTotal(total);
  }, [formData.parts]);

  const totalOS = partsTotal + formData.laborValue + formData.shippingValue - formData.discount;

  const handleToggleItem = (item: string) => {
    setFormData(prev => ({
      ...prev,
      itemsLeft: prev.itemsLeft.includes(item) 
        ? prev.itemsLeft.filter(i => i !== item)
        : [...prev.itemsLeft, item]
    }));
  };

  const handleToggleCondition = (condition: string) => {
    setFormData(prev => ({
      ...prev,
      physicalCondition: prev.physicalCondition.includes(condition) 
        ? prev.physicalCondition.filter(c => c !== condition)
        : [...prev.physicalCondition, condition]
    }));
  };

  const startCamera = async () => {
    setIsCameraOpen(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment' } });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
      }
    } catch (err) {
      console.error("Erro ao acessar câmera:", err);
      alert("Não foi possível acessar a câmera.");
      setIsCameraOpen(false);
    }
  };

  const stopCamera = () => {
    const stream = videoRef.current?.srcObject as MediaStream;
    stream?.getTracks().forEach(track => track.stop());
    setIsCameraOpen(false);
  };

  const takePhoto = () => {
    if (videoRef.current && canvasRef.current) {
      const context = canvasRef.current.getContext('2d');
      canvasRef.current.width = videoRef.current.videoWidth;
      canvasRef.current.height = videoRef.current.videoHeight;
      context?.drawImage(videoRef.current, 0, 0);
      const photoData = canvasRef.current.toDataURL('image/jpeg');
      setFormData(prev => ({ ...prev, photos: [...prev.photos, photoData] }));
      stopCamera();
    }
  };

  const removePhoto = (index: number) => {
    setFormData(prev => ({ ...prev, photos: prev.photos.filter((_, i) => i !== index) }));
  };

  const analyzeProblemWithIA = async () => {
    if (!formData.problemReported) return;
    setIsAnalyzing(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: `Como especialista técnico em celulares, analise o seguinte problema: "${formData.problemReported}". 
        Dê um diagnóstico técnico provável e sugira passos para o reparo em 3 tópicos curtos.`,
      });
      setFormData(prev => ({ ...prev, technicalDiagnosis: response.text || '' }));
    } catch (err) {
      console.error("Erro na IA:", err);
    } finally {
      setIsAnalyzing(false);
    }
  };

  const addPart = () => {
    setFormData(prev => ({
      ...prev,
      parts: [...prev.parts, { id: Date.now(), name: '', quantity: 1, unitPrice: 0 }]
    }));
  };

  const removePart = (id: number) => {
    setFormData(prev => ({
      ...prev,
      parts: prev.parts.filter(p => p.id !== id)
    }));
  };

  const updatePart = (id: number, field: string, value: any) => {
    setFormData(prev => ({
      ...prev,
      parts: prev.parts.map(p => p.id === id ? { ...p, [field]: value } : p)
    }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.clientName || !formData.model || !formData.imei) {
      alert("Por favor, preencha os campos obrigatórios: Cliente, Aparelho e IMEI.");
      return;
    }
    if (!formData.termsAccepted) {
      alert("O cliente precisa aceitar os termos de responsabilidade.");
      return;
    }
    onSave(formData);
  };

  return (
    <div className="max-w-5xl mx-auto pb-20 animate-in slide-in-from-right duration-300">
      {/* Câmera Modal */}
      {isCameraOpen && (
        <div className="fixed inset-0 bg-black z-[100] flex flex-col items-center justify-center">
          <video ref={videoRef} autoPlay playsInline className="w-full max-h-[80vh] object-contain" />
          <canvas ref={canvasRef} className="hidden" />
          <div className="flex gap-6 mt-8">
            <button onClick={stopCamera} className="w-16 h-16 bg-white/10 text-white rounded-full flex items-center justify-center backdrop-blur-md">
              <X size={32} />
            </button>
            <button onClick={takePhoto} className="w-20 h-20 bg-white rounded-full flex items-center justify-center border-4 border-blue-500 shadow-2xl">
              <div className="w-16 h-16 rounded-full border-2 border-black/5" />
            </button>
          </div>
        </div>
      )}

      {/* Header Fixo */}
      <div className="flex items-center justify-between mb-8 sticky top-0 bg-slate-50/80 backdrop-blur-md py-4 z-20">
        <div className="flex items-center gap-4">
          <button onClick={onBack} className="p-2 hover:bg-white rounded-full border border-transparent hover:border-slate-200 transition-all">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-slate-800 tracking-tight flex items-center gap-2">
              {formData.type === OSType.ORCAMENTO ? 'Novo Orçamento' : formData.type === OSType.GARANTIA ? 'Garantia' : 'Nova OS'}
              <span className="text-xs bg-blue-100 text-blue-700 px-2 py-0.5 rounded-full font-black uppercase">v2.0</span>
            </h1>
            <p className="text-slate-500 text-sm font-medium">Controle de entrada especializado.</p>
          </div>
        </div>
        <div className="flex gap-3">
          <button type="button" className="p-3 bg-white border border-slate-200 rounded-2xl text-slate-600 hover:text-blue-600 shadow-sm transition-all" title="Imprimir Recibo de Entrada">
            <Printer size={20} />
          </button>
          <button 
            type="submit" 
            form="os-form"
            className="flex items-center gap-2 bg-blue-600 text-white px-8 py-3 rounded-2xl font-bold hover:bg-blue-700 shadow-xl shadow-blue-200 transition-all active:scale-95"
          >
            <Save size={18} />
            Salvar Registro
          </button>
        </div>
      </div>

      <form id="os-form" onSubmit={handleSubmit} className="space-y-6">

        {/* Seletor de Tipo */}
        <div className="bg-white p-2 rounded-[1.5rem] border border-slate-100 shadow-sm flex gap-1">
          {Object.values(OSType).map((type) => (
            <button
              key={type}
              type="button"
              onClick={() => setFormData({...formData, type})}
              className={`flex-1 py-3 rounded-xl text-xs font-black transition-all uppercase tracking-widest ${
                formData.type === type 
                ? 'bg-blue-600 text-white shadow-lg shadow-blue-100' 
                : 'text-slate-400 hover:bg-slate-50'
              }`}
            >
              {type}
            </button>
          ))}
        </div>

        {/* Galeria de Evidências */}
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <div className="flex items-center justify-between mb-6">
            <div className="flex items-center gap-3">
              <div className="p-3 bg-rose-50 text-rose-600 rounded-2xl"><Camera size={20} /></div>
              <h2 className="font-black text-slate-800 uppercase text-xs tracking-[0.2em]">Evidências Fotográficas</h2>
            </div>
            <button 
              type="button" 
              onClick={startCamera}
              className="px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 hover:bg-slate-800 transition-all"
            >
              <Camera size={14} /> Abrir Câmera
            </button>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-5 gap-4">
            {formData.photos.map((photo, idx) => (
              <div key={idx} className="relative aspect-square rounded-2xl overflow-hidden border-2 border-slate-100 group">
                <img src={photo} alt="Evidência" className="w-full h-full object-cover" />
                <button 
                  type="button" 
                  onClick={() => removePhoto(idx)}
                  className="absolute top-2 right-2 p-1.5 bg-rose-600 text-white rounded-lg opacity-0 group-hover:opacity-100 transition-opacity"
                >
                  <Trash2 size={14} />
                </button>
              </div>
            ))}
            {formData.photos.length < 5 && (
              <button 
                type="button"
                onClick={startCamera}
                className="aspect-square rounded-2xl border-2 border-dashed border-slate-200 flex flex-col items-center justify-center gap-2 text-slate-400 hover:border-blue-400 hover:text-blue-500 hover:bg-blue-50/30 transition-all group"
              >
                <Plus size={24} className="group-hover:scale-110 transition-transform" />
                <span className="text-[10px] font-black uppercase tracking-widest">Foto</span>
              </button>
            )}
          </div>
          <p className="mt-4 text-[10px] text-slate-400 font-bold uppercase tracking-widest italic flex items-center gap-2">
            <ShieldCheck size={12} /> Fotos comprovam o estado físico do aparelho no ato do recebimento.
          </p>
        </div>

        {/* Seção 1: Cliente */}
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <div className="flex items-center gap-3 mb-6">
            <div className="p-3 bg-blue-50 text-blue-600 rounded-2xl"><UserPlus size={20} /></div>
            <h2 className="font-black text-slate-800 uppercase text-xs tracking-[0.2em]">Identificação do Cliente</h2>
          </div>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="relative">
              <label className="block text-[10px] font-black text-slate-400 uppercase mb-2 ml-1 tracking-widest">Localizar Cadastro *</label>
              <div className="relative">
                <input 
                  type="text" 
                  value={formData.clientName}
                  onChange={(e) => setFormData({...formData, clientName: e.target.value})}
                  className="w-full pl-12 pr-4 py-4 bg-white border border-slate-200 rounded-2xl focus:ring-2 focus:ring-blue-500 outline-none transition-all shadow-sm font-bold text-slate-700" 
                  placeholder="Nome, CPF ou Telefone..." 
                  required
                />
                <Search size={22} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
              </div>
            </div>
            <div className="flex items-end">
              <button type="button" className="flex items-center gap-2 text-blue-600 font-black text-xs hover:bg-blue-50 px-6 py-4 rounded-2xl transition-all border-2 border-dashed border-blue-100 uppercase tracking-widest">
                <Plus size={18} />
                Novo Cliente
              </button>
            </div>
          </div>
        </div>

        {/* Seção 2: Aparelho */}
        <div className="bg-white p-8 rounded-[2rem] border border-slate-100 shadow-sm">
          <div className="flex items-center gap-3 mb-8">
            <div className="p-3 bg-indigo-50 text-indigo-600 rounded-2xl"><Smartphone size={20} /></div>
            <h2 className="font-black text-slate-800 uppercase text-xs tracking-[0.2em]">Especificações do Aparelho</h2>
          </div>

