  Search, 
  Smartphone,
  CheckCircle2,
  Plus,
  X,
  Share2,
  Trash2,
  RefreshCcw
} from 'lucide-react';

interface CatalogItem {
  brand: string;
  model: string;
  char: string;
  master: number;
  import: number;
  premium: number;
  pro: number;
}

// Catálogo iniciado como vazio por solicitação do usuário
const INITIAL_CATALOG: CatalogItem[] = [];

const PreOrcamentoView: React.FC = () => {
  const [catalog, setCatalog] = useState<CatalogItem[]>(INITIAL_CATALOG);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedBrand, setSelectedBrand] = useState('TODOS');
  const [isAddingNew, setIsAddingNew] = useState(false);

  const [data, setData] = useState({
    device: '',
    partValue: 0,
    shippingValue: 0,
    laborValue: 0,
  });

  const [newModel, setNewModel] = useState<CatalogItem>({ 
    brand: 'APPLE', model: '', char: '', master: 0, import: 0, premium: 0, pro: 0 
  });

  const brands = ['TODOS', 'APPLE', 'SAMSUNG', 'MOTOROLA', 'XIAOMI', 'LG', 'ASUS', 'OUTROS'];

  const filteredCatalog = useMemo(() => {
    return catalog.filter(item => {
      const searchStr = `${item.brand} ${item.model} ${item.char}`.toLowerCase();
      const matchesSearch = searchStr.includes(searchTerm.toLowerCase());
      const matchesBrand = selectedBrand === 'TODOS' || 
                         (selectedBrand === 'OUTROS' && !['APPLE','SAMSUNG','MOTOROLA','XIAOMI','LG','ASUS'].includes(item.brand)) ||
                         item.brand === selectedBrand;
      return matchesSearch && matchesBrand;
    });
  }, [searchTerm, selectedBrand, catalog]);

  const total = data.partValue + data.shippingValue + data.laborValue;

  const handleSelectPrice = (price: number, item: CatalogItem) => {
    setData(prev => ({ 
      ...prev, 
      partValue: price, 
      device: `${item.brand} ${item.model} (${item.char})` 
    }));
  };

  const handleSaveNewModel = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newModel.model) return;
    setCatalog([newModel, ...catalog]);
    setIsAddingNew(false);
    setNewModel({ brand: 'APPLE', model: '', char: '', master: 0, import: 0, premium: 0, pro: 0 });
  };

  const clearCalculator = () => {
    setData({
      device: '',
      partValue: 0,
      shippingValue: 0,
      laborValue: 0,
    });
  };

  const removeModel = (index: number) => {
    const newCat = [...catalog];
    newCat.splice(index, 1);
    setCatalog(newCat);
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 pb-24 animate-in fade-in duration-500">
      {/* Header */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 flex items-center gap-3">
            <Calculator className="text-blue-600 w-9 h-9" /> Orçamento
          </h2>
          <p className="text-slate-500 font-medium">Catálogo de preços personalizado e calculadora de OS.</p>
        </div>
        <div className="flex gap-2 w-full md:w-auto">
          <button 
            onClick={() => setIsAddingNew(true)}
            className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-blue-600 text-white px-8 py-3 rounded-2xl font-bold shadow-xl shadow-blue-200 hover:bg-blue-700 transition-all active:scale-95"
          >
            <Plus size={20} /> Cadastrar Preço
          </button>
        </div>
      </div>

      {/* Modal Adição */}
      {isAddingNew && (
        <div className="fixed inset-0 bg-slate-900/80 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[2.5rem] w-full max-w-2xl shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
            <div className="p-8 border-b flex justify-between items-center bg-slate-50">
              <div>
                <h3 className="font-black text-xl text-slate-800 uppercase tracking-tight">Novo Item de Catálogo</h3>
                <p className="text-slate-500 text-sm">Alimente sua base de dados personalizada.</p>
              </div>
              <button onClick={() => setIsAddingNew(false)} className="p-3 hover:bg-slate-200 rounded-full transition-colors text-slate-400"><X size={24}/></button>
            </div>
            <form onSubmit={handleSaveNewModel} className="p-8 space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Fabricante</label>
                  <select 
                    value={newModel.brand}
                    onChange={e => setNewModel({...newModel, brand: e.target.value})}
                    className="w-full p-4 bg-white border border-slate-200 rounded-2xl font-bold focus:ring-2 focus:ring-blue-500 outline-none shadow-sm"
                  >
                    {brands.filter(b => b !== 'TODOS').map(b => <option key={b} value={b}>{b}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Modelo</label>
                  <input 
                    type="text" required placeholder="Ex: iPhone 13 Pro"
                    value={newModel.model}
                    onChange={e => setNewModel({...newModel, model: e.target.value})}
                    className="w-full p-4 bg-white border border-slate-200 rounded-2xl font-bold focus:ring-2 focus:ring-blue-500 outline-none shadow-sm" 
                  />
                </div>
              </div>
              <div>
                <label className="block text-[10px] font-black uppercase text-slate-400 mb-2 ml-1">Observação da Peça</label>
                <input 
                  type="text" placeholder="Ex: COM ARO / CI ORIGINAL"
                  value={newModel.char}
                  onChange={e => setNewModel({...newModel, char: e.target.value})}
                  className="w-full p-4 bg-white border border-slate-200 rounded-2xl font-bold focus:ring-2 focus:ring-blue-500 outline-none shadow-sm" 
                />
              </div>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
                {[
                  { key: 'master', label: 'Master' },
                  { key: 'import', label: 'Import' },
                  { key: 'premium', label: 'Premium' },
                  { key: 'pro', label: 'Sky Pro' }
                ].map(col => (
                  <div key={col.key}>
                    <label className="block text-[9px] font-black uppercase text-slate-500 mb-1 ml-1">{col.label}</label>
                    <input 
                      type="number" placeholder="0"
                      value={(newModel as any)[col.key]}
                      onChange={e => setNewModel({...newModel, [col.key]: Number(e.target.value)})}
                      className="w-full p-3 bg-white border border-slate-200 rounded-xl font-bold text-center outline-none focus:ring-2 focus:ring-blue-400 shadow-sm" 
                    />
                  </div>
                ))}
              </div>
              <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black text-lg shadow-xl shadow-blue-200 hover:bg-blue-700 transition-all uppercase tracking-widest active:scale-95">
                Salvar no Catálogo
              </button>
            </form>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">

        {/* Catálogo */}
        <div className="lg:col-span-8 space-y-6">
          <div className="bg-white p-6 rounded-[2.5rem] border border-slate-100 shadow-sm space-y-6">
            <div className="flex flex-col sm:flex-row gap-4 items-center">
              <div className="relative flex-1 w-full">
                <Search size={22} className="absolute left-5 top-1/2 -translate-y-1/2 text-slate-400" />
                <input 
                  type="text" 
                  placeholder="Pesquisar nos seus itens cadastrados..."
                  className="w-full pl-14 pr-6 py-4 bg-white border border-slate-200 rounded-[1.5rem] outline-none focus:bg-white focus:border-blue-500 text-sm font-semibold transition-all shadow-sm"
                  value={searchTerm}
                  onChange={e => setSearchTerm(e.target.value)}
                />
              </div>
            </div>

            <div className="flex gap-2 overflow-x-auto pb-4 no-scrollbar">
              {brands.map(b => (
                <button
                  key={b}
                  onClick={() => setSelectedBrand(b)}
                  className={`px-6 py-2.5 rounded-full text-[11px] font-black uppercase transition-all whitespace-nowrap border-2 ${
                    selectedBrand === b ? 'bg-blue-600 text-white border-blue-600 shadow-lg shadow-blue-200' : 'bg-white text-slate-500 border-slate-100 hover:bg-slate-50'
                  }`}
                >
                  {b}
                </button>
              ))}
            </div>

            <div className="min-h-[400px] max-h-[600px] overflow-y-auto rounded-3xl border border-slate-100 no-scrollbar relative">
              {catalog.length > 0 ? (
                <table className="w-full text-left border-collapse">
                  <thead className="sticky top-0 bg-white shadow-sm z-10">
                    <tr className="text-[10px] font-black text-slate-400 uppercase border-b-2 border-slate-50">
                      <th className="px-8 py-5">Item Cadastrado</th>
                      <th className="px-2 py-5 text-center">Master</th>
                      <th className="px-2 py-5 text-center">Import</th>
                      <th className="px-2 py-5 text-center">Premium</th>
                      <th className="px-2 py-5 text-center">Sky Pro</th>
                      <th className="px-2 py-5 text-center"></th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {filteredCatalog.map((item, idx) => (
                      <tr key={idx} className="hover:bg-blue-50/20 transition-all group">
                        <td className="px-8 py-5">
                          <div className="flex items-center gap-4">
                            <Smartphone size={20} className="text-slate-400" />
                            <div>
                              <p className="text-sm font-black text-slate-800">{item.model}</p>
                              <p className="text-[10px] text-slate-400 font-bold uppercase">{item.brand} • {item.char || 'Universal'}</p>
                            </div>
                          </div>
                        </td>
                        <td className="px-2 py-5">
                          <button onClick={() => handleSelectPrice(item.master, item)} className="w-full py-2 bg-white border border-slate-200 text-slate-600 text-[11px] font-black rounded-lg hover:bg-slate-50 shadow-sm transition-all">R$ {item.master}</button>
                        </td>
                        <td className="px-2 py-5">
                          <button onClick={() => handleSelectPrice(item.import, item)} className="w-full py-2 bg-white border border-emerald-100 text-emerald-700 text-[11px] font-black rounded-lg hover:bg-emerald-50 shadow-sm transition-all">R$ {item.import}</button>
                        </td>
                        <td className="px-2 py-5">
                          <button onClick={() => handleSelectPrice(item.premium, item)} className="w-full py-2 bg-white border border-amber-100 text-amber-700 text-[11px] font-black rounded-lg hover:bg-amber-50 shadow-sm transition-all">R$ {item.premium}</button>
                        </td>
                        <td className="px-2 py-5">
                          <button onClick={() => handleSelectPrice(item.pro, item)} className="w-full py-2 bg-blue-600 text-white text-[11px] font-black rounded-lg hover:bg-blue-700 shadow-md">R$ {item.pro}</button>
                        </td>
                        <td className="px-4 py-5 text-center">
                          <button onClick={() => removeModel(idx)} className="p-2 text-slate-300 hover:text-rose-500 transition-colors"><Trash2 size={16}/></button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              ) : null}
            </div>
          </div>
        </div>

        {/* Calculadora Lateral */}
        <div className="lg:col-span-4 space-y-6">
          <div className="bg-white p-8 rounded-[3rem] border border-slate-100 shadow-2xl space-y-8 sticky top-24">
            <div className="flex items-center justify-between border-b border-slate-50 pb-6">
              <div className="flex items-center gap-4">
                <div className="p-3.5 bg-blue-600 text-white rounded-2xl shadow-xl shadow-blue-100">
                  <Calculator size={24} />
                </div>
                <h3 className="font-black text-slate-800 uppercase tracking-widest text-lg">Cálculo Atual</h3>
              </div>
              <button onClick={clearCalculator} title="Limpar Tudo" className="p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all"><RefreshCcw size={20}/></button>
            </div>

            <div className="space-y-6">
              <div>
                <label className="block text-[10px] font-black text-slate-400 uppercase mb-3 ml-2 tracking-widest">Aparelho Selecionado</label>
                <div className="p-4 bg-white rounded-2xl border-2 border-slate-100 focus-within:border-blue-500 transition-all shadow-sm">
                  <input 
                    type="text" 
                    value={data.device}
                    onChange={e => setData({...data, device: e.target.value})}
                    className="w-full bg-white font-black text-slate-800 placeholder:font-normal outline-none text-sm" 
                    placeholder="Selecione um preço ou digite..."
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div className="p-5 bg-white rounded-[2.5rem] border border-slate-100 shadow-sm">
                  <label className="flex items-center gap-2 text-[9px] font-black text-slate-500 uppercase mb-3 tracking-widest">
                    <Package size={14} className="text-blue-500" /> Peça
                  </label>
                  <div className="flex items-center gap-1 text-slate-800">
                    <span className="font-black text-slate-300">R$</span>
                    <input 
                      type="number" 
                      value={data.partValue}
                      onChange={e => setData({...data, partValue: Number(e.target.value)})}
                      className="w-full bg-white text-xl font-black outline-none" 
                    />
                  </div>
                </div>
                <div className="p-5 bg-white rounded-[2.5rem] border border-slate-100 shadow-sm">
                  <label className="flex items-center gap-2 text-[9px] font-black text-slate-500 uppercase mb-3 tracking-widest">
                    <Truck size={14} className="text-emerald-500" /> Frete
                  </label>
                  <div className="flex items-center gap-1 text-slate-800">
                    <span className="font-black text-slate-300">R$</span>
                    <input 
                      type="number" 
                      value={data.shippingValue}
                      onChange={e => setData({...data, shippingValue: Number(e.target.value)})}
                      className="w-full bg-white text-xl font-black outline-none" 
                    />
                  </div>
                </div>
              </div>

              <div className="p-6 bg-white rounded-[2.5rem] border border-indigo-100 shadow-sm">
                <label className="flex items-center gap-2 text-[10px] font-black text-indigo-600 uppercase mb-4 tracking-widest">
                  <DollarSign size={20} /> Mão de Obra + Lucro
                </label>
                <div className="flex items-center gap-2 text-indigo-900">
                  <span className="font-black text-indigo-300 text-3xl">R$</span>
                  <input 
                    type="number" 
                    value={data.laborValue}
                    onChange={e => setData({...data, laborValue: Number(e.target.value)})}
                    className="w-full bg-white text-4xl font-black outline-none" 
                    placeholder="0"
                  />
                </div>
              </div>
            </div>

            <div className="bg-slate-900 text-white p-10 rounded-[3.5rem] shadow-2xl relative overflow-hidden group">
              <div className="absolute top-0 right-0 w-48 h-48 bg-blue-500/10 rounded-full blur-[80px] -mr-20 -mt-20 group-hover:bg-blue-500/20 transition-all duration-700"></div>
              <p className="text-[10px] font-black text-blue-400 uppercase tracking-[0.4em] mb-4">Total para o Cliente</p>
              <div className="flex items-baseline gap-3">
                <span className="text-2xl font-bold text-slate-500">R$</span>
                <h4 className="text-6xl font-black text-white tracking-tighter">{total.toFixed(2)}</h4>
              </div>

              <div className="mt-10 pt-8 border-t border-white/10 flex flex-col gap-4">
                 <div className="flex justify-between items-center bg-emerald-500/10 p-4 rounded-2xl">
                    <span className="text-[10px] font-black text-emerald-500 uppercase tracking-widest">Lucro Bruto OS:</span>
                    <span className="text-2xl font-black text-emerald-400">R$ {data.laborValue.toFixed(2)}</span>
                 </div>
              </div>
            </div>

            <button className="w-full py-6 bg-blue-600 text-white rounded-[2rem] font-black text-sm hover:bg-blue-700 transition-all flex items-center justify-center gap-3 shadow-2xl shadow-blue-200 uppercase tracking-widest active:scale-95 group">
               <CheckCircle2 size={24} /> Criar Orçamento Final
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

