import ShoppingListView from './views/ShoppingListView';
import LoginView from './views/LoginView';

const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState<boolean>(false);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isCreatingOS, setIsCreatingOS] = useState(false);

  // Verifica se existe sessão salva no carregamento
  useEffect(() => {
    const session = localStorage.getItem('asim_session');
    if (session) setIsAuthenticated(true);
  }, []);

  const handleLogin = (user: string, pass: string) => {
    // Aqui no futuro chamaremos a api.login() real
    localStorage.setItem('asim_session', 'mock_token_123');
    setIsAuthenticated(true);
  };

  const handleLogout = () => {
    localStorage.removeItem('asim_session');
    setIsAuthenticated(false);
  };

  const handleNewOS = () => {
    setActiveTab('os');
    setIsCreatingOS(true);
  };

  const handleSaveOS = (data: any) => {
    console.log("Salvando OS no Backend:", data);
    alert("Ordem de Serviço salva com sucesso!");
    setIsCreatingOS(false);
  };

  // Se não estiver logado, renderiza apenas a tela de login
  if (!isAuthenticated) {
    return <LoginView onLogin={handleLogin} />;
  }

  const renderContent = () => {
    switch (activeTab) {
      case 'dashboard':
        return <Dashboard onNewOS={handleNewOS} onViewAllOS={() => setActiveTab('os')} />;
      case 'os':
        return isCreatingOS ? 
          <ServiceOrderForm onBack={() => setIsCreatingOS(false)} onSave={handleSaveOS} /> : 
          <ServiceOrdersList onNewOS={() => setIsCreatingOS(true)} />;
      case 'clientes':
        return <ClientsView />;
      case 'fornecedores':
        return <SuppliersView />;
      case 'lista-compras':
        return <ShoppingListView />;
      case 'estoque':
      case 'produtos':
        return <InventoryView />;
      case 'caixa':
        return <CashView />;
      case 'pre-orcamento':
        return <PreOrcamentoView />;
      case 'configuracoes':
        return <SettingsView />;
      default:
        return (
          <div className="flex flex-col items-center justify-center h-64 text-slate-400">
            <h2 className="text-xl font-bold italic">Seção em Desenvolvimento</h2>
          </div>
        );
    }
  };

  return (
    <Layout activeTab={activeTab} setActiveTab={(tab) => {
      setActiveTab(tab);
      setIsCreatingOS(false);
    }}>
      {renderContent()}
    </Layout>
  );
};

