                    {editingUser?.id === currentUser.id ? 'Personalizar Meu Perfil' : (editingUser ? 'Editar Técnico' : 'Novo Acesso')}
                </h3>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Configurações de Segurança Asim</p>
