import React, { useState, useEffect } from 'react';
import { UserPlus, Trash2, Shield, Wrench, User, X, Check, AlertCircle, Edit3, Key, Save, LogOut } from 'lucide-react';
import { api } from '../services/api';
import { User as UserType } from '../types';

interface UserManagementViewProps {
  currentUser: UserType;
  onUpdateSelf: (updated: UserType) => void;
}

const UserManagementView: React.FC<UserManagementViewProps> = ({ currentUser, onUpdateSelf }) => {
  const [users, setUsers] = useState<UserType[]>([]);
  const [showAddForm, setShowAddForm] = useState(false);
  const [editingUser, setEditingUser] = useState<UserType | null>(null);
  const [newUser, setNewUser] = useState({ name: '', username: '', password: '', role: 'TECNICO' as 'TECNICO' | 'ADMIN' });
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const loadUsers = async () => {
    const list = await api.getUsersList();
    setUsers(list);
  };

  useEffect(() => { loadUsers(); }, []);

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    const result = await api.addUser(newUser);
    if (result.success) {
      setShowAddForm(false);
      setNewUser({ name: '', username: '', password: '', role: 'TECNICO' });
      loadUsers();
      setSuccess('Usuário cadastrado com sucesso!');
      setTimeout(() => setSuccess(''), 3000);
    } else {
      setError(result.message);
    }
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingUser) return;

    try {
      const updated = await api.updateUser(editingUser.id, editingUser);
      if (editingUser.id === currentUser.id) {
        onUpdateSelf(updated);
      }
      setEditingUser(null);
      loadUsers();
      setSuccess('Dados atualizados com sucesso!');
      setTimeout(() => setSuccess(''), 3000);
    } catch (err) {
      setError('Erro ao atualizar usuário');
    }
  };

  const handleDelete = async (id: string) => {
    if (confirm('Remover este acesso permanentemente?')) {
      await api.removeUser(id);
      loadUsers();
    }
  };

  const handleSwitchUser = () => {
    if (confirm("Deseja sair para entrar com outro usuário?")) {
      localStorage.removeItem('asim_session');
      window.location.reload();
    }
  };

  const limitReached = users.length >= 3;

  return (
    <div className="max-w-5xl mx-auto space-y-12 animate-in fade-in duration-500 pb-20">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight">Gestão de Equipe & Acessos</h2>
          <p className="text-slate-500 font-medium">Controle quem pode operar o sistema da sua loja.</p>
        </div>
        <div className="flex items-center gap-4">
            {success && <div className="bg-emerald-50 text-emerald-600 px-4 py-2 rounded-xl text-xs font-black animate-bounce flex items-center gap-2"><Check size={14}/> {success}</div>}
            <div className="bg-white px-6 py-3 rounded-2xl border border-slate-100 flex items-center gap-3 shadow-sm">
               <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse"></div>
               <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Usuários Extras: <span className="text-slate-800">{users.length-1} / 2</span></span>
            </div>
        </div>
      </div>

      {/* Seção Meu Perfil */}
      <section className="bg-slate-900 rounded-[3rem] p-8 md:p-12 text-white shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 w-64 h-64 bg-blue-600/10 rounded-full blur-[100px] -mr-32 -mt-32"></div>
        <div className="relative z-10 flex flex-col lg:flex-row items-center gap-8">
            <div className="w-24 h-24 bg-blue-600 rounded-[2rem] flex items-center justify-center shadow-2xl shadow-blue-500/20 flex-shrink-0">
                <Shield size={48} />
            </div>
            <div className="flex-1 text-center lg:text-left">
                <div className="flex flex-col md:flex-row md:items-center gap-2 md:gap-4 mb-2 justify-center lg:justify-start">
                    <h3 className="text-2xl font-black uppercase tracking-tight">{currentUser.name}</h3>
                    <span className="bg-blue-600/20 text-blue-400 px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest">Administrador Master</span>
                </div>
                <p className="text-slate-400 font-bold text-sm">Este é o seu perfil de proprietário. Personalize sua identidade aqui.</p>
                <div className="mt-4 flex flex-wrap justify-center lg:justify-start gap-4">
                    <div className="px-4 py-2 bg-white/5 border border-white/10 rounded-xl text-xs font-bold text-slate-400">Login: <span className="text-white">@{currentUser.username}</span></div>
                </div>
            </div>
            <div className="flex flex-col sm:flex-row gap-3 w-full lg:w-auto">
                <button 
                    onClick={() => setEditingUser(users.find(u => u.id === currentUser.id) || null)}
                    className="flex-1 lg:flex-none px-8 py-4 bg-white text-slate-900 rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-blue-500 hover:text-white transition-all active:scale-95 shadow-xl flex items-center justify-center gap-2"
                >
                    <Edit3 size={18} /> Editar Perfil
                </button>
                <button 
                    onClick={handleSwitchUser}
                    className="flex-1 lg:flex-none px-6 py-4 bg-white/5 border border-white/10 text-white rounded-2xl font-black text-xs uppercase tracking-widest hover:bg-rose-600 transition-all flex items-center justify-center gap-2"
                >
                    <LogOut size={18} /> Trocar Conta
                </button>
            </div>
        </div>
      </section>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="md:col-span-2 flex items-center justify-between px-2">
            <h3 className="text-xs font-black uppercase text-slate-400 tracking-[0.3em]">Lista de Colaboradores</h3>
        </div>

        {users.filter(u => u.id !== currentUser.id).map((u) => (
          <div key={u.id} className="bg-white p-8 rounded-[2.5rem] border border-slate-100 shadow-sm relative group overflow-hidden">
            <div className="flex items-center gap-6">
              <div className={`w-16 h-16 rounded-3xl flex items-center justify-center ${u.role === 'ADMIN' ? 'bg-blue-50 text-blue-600' : 'bg-slate-50 text-slate-600'}`}>
                {u.role === 'ADMIN' ? <Shield size={32} /> : <User size={32} />}
              </div>
              <div className="flex-1 min-w-0">
                <h3 className="font-black text-slate-800 truncate">{u.name}</h3>
                <p className="text-xs font-bold text-slate-400 uppercase tracking-widest">@{u.username} • {u.role === 'ADMIN' ? 'Admin' : 'Usuário'}</p>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={() => setEditingUser(u)}
                  className="p-3 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-2xl transition-all"
                >
                  <Edit3 size={20} />
                </button>
                <button 
                  onClick={() => handleDelete(u.id)}
                  className="p-3 text-slate-200 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all"
                >
                  <Trash2 size={20} />
                </button>
              </div>
            </div>
          </div>
        ))}

        {!limitReached ? (
          <button 
            onClick={() => { setShowAddForm(true); setEditingUser(null); }}
            className="md:col-span-2 bg-blue-50 border-2 border-dashed border-blue-200 p-10 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 text-blue-500 hover:bg-blue-100 hover:border-blue-300 transition-all group"
          >
            <div className="w-16 h-16 bg-white rounded-3xl flex items-center justify-center shadow-sm group-hover:scale-110 transition-transform">
              <UserPlus size={32} />
            </div>
            <div className="text-center">
                <span className="font-black text-sm uppercase tracking-widest block">Adicionar Novo Usuário</span>
                <p className="text-[10px] font-bold text-blue-400 uppercase mt-1">Crie um acesso para um novo funcionário</p>
            </div>
          </button>
        ) : (
          <div className="md:col-span-2 border-4 border-dashed border-slate-100 p-10 rounded-[2.5rem] flex flex-col items-center justify-center gap-4 text-slate-200 opacity-50 grayscale">
            <div className="w-16 h-16 bg-slate-50 rounded-3xl flex items-center justify-center">
              <Shield size={32} />
            </div>
            <span className="font-black text-[9px] uppercase tracking-[0.2em] text-center">Limite de Usuários Extras Atingido</span>
          </div>
        )}
      </div>

      {/* Modal Unificado */}
      {(showAddForm || editingUser) && (
        <div className="fixed inset-0 bg-slate-900/95 backdrop-blur-md z-[100] flex items-center justify-center p-4">
          <div className="bg-white rounded-[3rem] w-full max-w-md shadow-2xl animate-in zoom-in duration-200 overflow-hidden">
            <div className="p-8 border-b flex justify-between items-center bg-slate-50">
              <div>
                <h3 className="font-black text-slate-800 uppercase tracking-tight">
                    {editingUser?.id === currentUser.id ? 'Personalizar Perfil' : (editingUser ? 'Editar Usuário' : 'Novo Usuário')}
                </h3>
                <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Controle de Acessos Operacionais</p>
              </div>
              <button onClick={() => { setShowAddForm(false); setEditingUser(null); }} className="p-3 text-slate-400 hover:text-slate-800 hover:bg-slate-200 rounded-full transition-all"><X size={24}/></button>
            </div>
            <form onSubmit={editingUser ? handleUpdate : handleAdd} className="p-10 space-y-6">
              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 mb-1 block ml-1">Nome Completo do Usuário</label>
                  <input 
                    required type="text" 
                    value={editingUser ? editingUser.name : newUser.name} 
                    onChange={e => editingUser ? setEditingUser({...editingUser, name: e.target.value}) : setNewUser({...newUser, name: e.target.value})} 
                    className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold focus:ring-2 focus:ring-blue-500 outline-none" 
                    placeholder="Ex: João da Recepção"
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 mb-1 block ml-1">Login (@)</label>
                  <input 
                    required type="text" 
                    value={editingUser ? editingUser.username : newUser.username} 
                    onChange={e => editingUser ? setEditingUser({...editingUser, username: e.target.value}) : setNewUser({...newUser, username: e.target.value})} 
                    className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold focus:ring-2 focus:ring-blue-500 outline-none" 
                    placeholder="ex: joao.recepcao"
                  />
                </div>
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 mb-1 block ml-1">Senha de Acesso</label>
                  <div className="relative">
                    <input 
                        required={!editingUser} 
                        type="password" 
                        value={editingUser ? editingUser.password : newUser.password} 
                        onChange={e => editingUser ? setEditingUser({...editingUser, password: e.target.value}) : setNewUser({...newUser, password: e.target.value})} 
                        className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold pr-12 focus:ring-2 focus:ring-blue-500 outline-none" 
                        placeholder="Senha de entrada"
                    />
                    <Key size={20} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300" />
                  </div>
                </div>
                {!editingUser && (
                  <div>
                    <label className="text-[10px] font-black uppercase text-slate-400 mb-1 block ml-1">Perfil de Permissão</label>
                    <select value={newUser.role} onChange={e => setNewUser({...newUser, role: e.target.value as any})} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none focus:ring-2 focus:ring-blue-500">
                      <option value="TECNICO">Usuário (OS, Clientes e Estoque)</option>
                      <option value="ADMIN">Administrador (Acesso Total)</option>
                    </select>
                  </div>
                )}
              </div>

              {error && <div className="flex items-center gap-2 text-rose-500 text-xs font-bold p-3 bg-rose-50 rounded-xl"><AlertCircle size={14}/> {error}</div>}

              <button type="submit" className="w-full py-5 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-blue-100 hover:bg-blue-700 active:scale-95 transition-all flex items-center justify-center gap-3">
                <Save size={18} />
                {editingUser ? 'Salvar Alterações' : 'Criar Novo Usuário'}
              </button>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default UserManagementView;

import React, { useState, useEffect } from 'react';
import { MENU_ITEMS } from '../constants';
import { Menu, X, Bell, User as UserIcon, LogOut, Users as UsersIcon } from 'lucide-center';
import { User } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  setActiveTab: (tab: string) => void;
  user: User;
}

const Layout: React.FC<LayoutProps> = ({ children, activeTab, setActiveTab, user }) => {
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [config, setConfig] = useState({ logo: '', name: 'Painel da Asim' });

  useEffect(() => {
    const saved = localStorage.getItem('app_config');
    if (saved) setConfig(JSON.parse(saved));
  }, []);

  const handleLogout = () => {
    if (confirm("Deseja sair do sistema?")) {
      localStorage.removeItem('asim_session');
      window.location.reload();
    }
  };

  // Filtrar menu por papel
  const visibleMenuItems = MENU_ITEMS.filter(item => {
    if (user.role === 'TECNICO') {
      return !['caixa', 'fornecedores', 'configuracoes'].includes(item.id);
    }
    return true;
  });

  return (
    <div className="min-h-screen flex flex-col md:flex-row overflow-hidden">
      <header className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-50">
        <h1 className="text-xl font-bold text-blue-600">{config.name}</h1>
        <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-100 rounded-md">
          {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </header>

      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-40 md:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <aside className={`fixed md:relative top-0 bottom-0 left-0 w-64 bg-white border-r z-50 transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'} flex flex-col`}>
        <div className="p-8 hidden md:block border-b mb-4">
          {config.logo ? <img src={config.logo} alt="Logo" className="max-h-16 w-full object-contain" /> : <h1 className="text-2xl font-bold text-blue-600">{config.name}</h1>}
        </div>

        <nav className="flex-1 px-4 py-4 space-y-1">
          {visibleMenuItems.map((item) => (
            <button key={item.id} onClick={() => { setActiveTab(item.id); setIsSidebarOpen(false); }} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-colors ${activeTab === item.id ? 'bg-blue-600 text-white shadow-md' : 'text-slate-600 hover:bg-slate-50'}`}>
              {item.icon} {item.label}
            </button>
          ))}

          {user.role === 'ADMIN' && (
            <button onClick={() => { setActiveTab('usuarios'); setIsSidebarOpen(false); }} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-colors ${activeTab === 'usuarios' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-600 hover:bg-slate-50'}`}>
              <UsersIcon size={20} /> Gestão de Equipe
            </button>
          )}
        </nav>

        <div className="p-4 border-t mt-auto space-y-2">
          <div className="flex items-center gap-3 p-2 bg-slate-50 rounded-2xl border border-slate-100">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center ${user.role === 'ADMIN' ? 'bg-blue-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
              <UserIcon size={18} />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-bold truncate">{user.name}</p>
              <p className="text-[9px] font-black uppercase text-blue-500 tracking-widest">{user.role === 'ADMIN' ? 'Administrador' : 'Usuário'}</p>
            </div>
          </div>
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-2 text-rose-500 hover:bg-rose-50 rounded-xl text-xs font-black uppercase tracking-widest transition-all">
            <LogOut size={16} /> Sair do Painel
          </button>
        </div>
