      setError(result.message);
    }
  };

  const handleUpdate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingUser) return;

    try {
      const updated = await api.updateUser(editingUser.id, editingUser);
      if (editingUser.id === currentUser.id) {
        onUpdateSelf(updated);
      }
      setEditingUser(null);
      loadUsers();
