const STORAGE_KEY = 'asim_db_v1';
const USERS_KEY = 'asim_users_v1';
const LOGS_KEY = 'asim_logs_v1';

const getDb = () => {
  const data = localStorage.getItem(STORAGE_KEY);
  return data ? JSON.parse(data) : { clients: [], os: [], products: [], transactions: [] };
};

const saveDb = (db: any) => {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(db));
};

const getCurrentUser = (): User | null => {
  const session = localStorage.getItem('asim_session');
  return session ? JSON.parse(session) : null;
};

const registerLog = (action: string, details: string, severity: ActivityLog['severity'] = 'info') => {
  const user = getCurrentUser();
  const logsData = localStorage.getItem(LOGS_KEY);
  const logs: ActivityLog[] = logsData ? JSON.parse(logsData) : [];

  const newLog: ActivityLog = {
    id: Math.random().toString(36).substr(2, 9),
    userId: user?.id || 'system',
    userName: user?.name || 'Sistema',
    action,
    details,
    severity,
    timestamp: new Date().toISOString()
  };

  logs.unshift(newLog); // Novo log no topo
  localStorage.setItem(LOGS_KEY, JSON.stringify(logs.slice(0, 500))); // Mantém últimos 500 logs
};

const getUsers = (): User[] => {
  const data = localStorage.getItem(USERS_KEY);
  if (!data) {
    const admin: User = { 
      id: 'admin-1', 
      username: 'admin', 
      password: '123', 
      name: 'Administrador Asim', 
      role: 'ADMIN', 
      createdAt: new Date().toISOString() 
    };
    localStorage.setItem(USERS_KEY, JSON.stringify([admin]));
    return [admin];
  }
  return JSON.parse(data);
};

export const api = {
  // --- AUDITORIA ---
  getLogs: async (): Promise<ActivityLog[]> => {
    const data = localStorage.getItem(LOGS_KEY);
    return data ? JSON.parse(data) : [];
  },

  // --- USUÁRIOS E AUTH ---
  login: async (username: string, pass: string): Promise<User | null> => {
    const users = getUsers();
    const user = users.find(u => u.username === username && u.password === pass);
    if (user) {
      registerLog('Login', `Usuário ${user.username} acessou o sistema`);
      const { password, ...userWithoutPass } = user;
      return userWithoutPass as User;
    }
    registerLog('Falha de Login', `Tentativa de acesso com usuário: ${username}`, 'warning');
    return null;
  },

  getUsersList: async (): Promise<User[]> => {
    return getUsers();
  },

  addUser: async (userData: Omit<User, 'id' | 'createdAt'>): Promise<{success: boolean, message: string}> => {
    const users = getUsers();
    if (users.length >= 3) {
      return { success: false, message: 'Limite de usuários atingido.' };
    }
    const newUser = {
      ...userData,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: new Date().toISOString()
    };
    users.push(newUser);
    localStorage.setItem(USERS_KEY, JSON.stringify(users));
    registerLog('Criação de Usuário', `Novo usuário criado: ${newUser.name} (${newUser.role})`, 'info');
    return { success: true, message: 'Usuário cadastrado com sucesso.' };
  },

  updateUser: async (id: string, updates: Partial<User>): Promise<User> => {
    const users = getUsers();
    const index = users.findIndex(u => u.id === id);
    if (index === -1) throw new Error("Usuário não encontrado");

    users[index] = { ...users[index], ...updates };
    localStorage.setItem(USERS_KEY, JSON.stringify(users));
    registerLog('Alteração de Perfil', `Perfil de ${users[index].name} atualizado`, 'warning');

    const { password, ...userWithoutPass } = users[index];
    return userWithoutPass as User;
  },

  removeUser: async (id: string): Promise<void> => {
    const users = getUsers();
    const userToDelete = users.find(u => u.id === id);
    if (userToDelete?.id === 'admin-1') return;

    const filtered = users.filter(u => u.id !== id);
    localStorage.setItem(USERS_KEY, JSON.stringify(filtered));
    registerLog('Remoção de Usuário', `Acesso de ${userToDelete?.name} removido permanentemente`, 'danger');
  },

  // --- ORDENS DE SERVIÇO ---
  createOS: async (osData: any): Promise<ServiceOrder> => {
    const db = getDb();
    const newOS = {
      ...osData,
      id: Math.random().toString(36).substr(2, 9),
      osNumber: (db.os.length + 1001).toString(),
      openedAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      status: OSStatus.RECEBIDO
    };
    db.os.push(newOS);
    saveDb(db);
    registerLog('Nova OS', `OS #${newOS.osNumber} aberta para ${newOS.clientName}`, 'info');
    return newOS;
  },

  updateOSStatus: async (id: string, newStatus: OSStatus): Promise<void> => {
    const db = getDb();
    const os = db.os.find((o: ServiceOrder) => o.id === id);
    if (os) {
      const oldStatus = os.status;
      os.status = newStatus;
      os.updatedAt = new Date().toISOString();
      saveDb(db);
      registerLog('Status OS Alterado', `OS #${os.osNumber} mudou de [${oldStatus}] para [${newStatus}]`, 'info');
    }
  },

  // (Outras funções mantidas conforme original...)
  getClients: async (): Promise<Client[]> => getDb().clients,
  saveClient: async (client: any) => {
    const db = getDb();
    const newC = {...client, id: Math.random().toString(36).substr(2, 9), createdAt: new Date().toISOString()};
    db.clients.push(newC);
    saveDb(db);
    registerLog('Novo Cliente', `Cadastro de ${newC.name} realizado`, 'info');
    return newC;
  },
  getInventory: async (): Promise<Product[]> => getDb().products,
  getDeadStock: async (): Promise<Product[]> => {
    const db = getDb();
    const sixtyDaysAgo = new Date();
    sixtyDaysAgo.setDate(sixtyDaysAgo.getDate() - 60);
    return db.products.filter((p: Product) => p.lastSaleAt && new Date(p.lastSaleAt) < sixtyDaysAgo && p.quantity > 0);
  },
  saveProduct: async (product: any) => {
    const db = getDb();
    const newP = {...product, id: Math.random().toString(36).substr(2, 9), createdAt: new Date().toISOString(), lastSaleAt: new Date().toISOString()};
    db.products.push(newP);
    saveDb(db);
    registerLog('Novo Produto', `Item ${newP.name} adicionado ao estoque`, 'info');
    return newP;
  }
};

import React, { useState, useEffect } from 'react';
import { api } from '../services/api';
import { ActivityLog } from '../types';
import { History, Search, ShieldAlert, Info, AlertTriangle, Clock, User as UserIcon } from 'lucide-react';

const AuditLogsView: React.FC = () => {
  const [logs, setLogs] = useState<ActivityLog[]>([]);
  const [filter, setFilter] = useState('');

  useEffect(() => {
    api.getLogs().then(setLogs);
  }, []);

  const filteredLogs = logs.filter(log => 
    log.action.toLowerCase().includes(filter.toLowerCase()) || 
    log.userName.toLowerCase().includes(filter.toLowerCase()) ||
    log.details.toLowerCase().includes(filter.toLowerCase())
  );

  const getSeverityStyle = (severity: ActivityLog['severity']) => {
    switch(severity) {
      case 'danger': return 'bg-rose-50 text-rose-600 border-rose-100';
      case 'warning': return 'bg-amber-50 text-amber-600 border-amber-100';
      default: return 'bg-blue-50 text-blue-600 border-blue-100';
    }
  };

  const getSeverityIcon = (severity: ActivityLog['severity']) => {
    switch(severity) {
      case 'danger': return <ShieldAlert size={14} />;
      case 'warning': return <AlertTriangle size={14} />;
      default: return <Info size={14} />;
    }
  };

  return (
    <div className="max-w-6xl mx-auto space-y-8 animate-in fade-in duration-500 pb-24">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h2 className="text-3xl font-black text-slate-800 tracking-tight flex items-center gap-3">
            <History size={32} className="text-slate-400" /> Linha do Tempo da Loja
          </h2>
          <p className="text-slate-500 font-medium">Auditoria completa de todas as ações realizadas no painel.</p>
        </div>
        <div className="relative w-full md:w-80">
          <Search size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
          <input 
            type="text" 
            placeholder="Filtrar por ação ou usuário..." 
            className="w-full pl-12 pr-4 py-3 bg-white border border-slate-200 rounded-2xl font-bold outline-none shadow-sm focus:ring-2 focus:ring-blue-500"
            value={filter}
            onChange={e => setFilter(e.target.value)}
          />
        </div>
      </div>

      <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b">
                <th className="px-8 py-5">Quando</th>
                <th className="px-6 py-5">Responsável</th>
                <th className="px-6 py-5">Ação</th>
                <th className="px-8 py-5">Detalhes do Registro</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-50">
              {filteredLogs.map((log) => (
                <tr key={log.id} className="hover:bg-slate-50/50 transition-colors">
                  <td className="px-8 py-6 whitespace-nowrap">
                    <div className="flex items-center gap-3 text-slate-500 font-bold text-xs">
                      <Clock size={14} className="text-slate-300" />
                      {new Date(log.timestamp).toLocaleString('pt-BR', { 
                        day: '2-digit', 
                        month: '2-digit', 
                        hour: '2-digit', 
                        minute: '2-digit' 
                      })}
                    </div>
                  </td>
                  <td className="px-6 py-6">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-full bg-slate-100 flex items-center justify-center text-slate-400">
                        <UserIcon size={14} />
                      </div>
                      <span className="text-sm font-black text-slate-700">{log.userName}</span>
                    </div>
                  </td>
                  <td className="px-6 py-6">
                    <span className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest border flex items-center gap-2 w-fit ${getSeverityStyle(log.severity)}`}>
                      {getSeverityIcon(log.severity)}
                      {log.action}
                    </span>
                  </td>
                  <td className="px-8 py-6">
                    <p className="text-sm font-medium text-slate-600 leading-relaxed">{log.details}</p>
                  </td>
                </tr>
              ))}
              {filteredLogs.length === 0 && (
                <tr>
                  <td colSpan={4} className="py-20 text-center">
                    <History size={48} className="mx-auto text-slate-100 mb-4" />
                    <p className="text-slate-400 font-black uppercase text-xs tracking-widest">Nenhum registro encontrado</p>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default AuditLogsView;

import React, { useState, useEffect } from 'react';
import Layout from './components/Layout';
import Dashboard from './views/Dashboard';
import ClientsView from './views/ClientsView';
import SuppliersView from './views/SuppliersView';
import ServiceOrdersList from './views/ServiceOrdersList';
import ServiceOrderForm from './views/ServiceOrderForm';
import InventoryView from './views/InventoryView';
import CashView from './views/CashView';
import PreOrcamentoView from './views/PreOrcamentoView';
import SettingsView from './views/SettingsView';
import ShoppingListView from './views/ShoppingListView';
import LoginView from './views/LoginView';
import UserManagementView from './views/UserManagementView';
import AuditLogsView from './views/AuditLogsView';
import { User } from './types';
import { api } from './services/api';

const App: React.FC = () => {
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isCreatingOS, setIsCreatingOS] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('asim_session');
    if (saved) {
      try {
        setCurrentUser(JSON.parse(saved));
      } catch (e) {
        localStorage.removeItem('asim_session');
      }
    }
  }, []);

  const handleLogin = async (user: string, pass: string): Promise<boolean> => {
    const authenticated = await api.login(user, pass);
    if (authenticated) {
      localStorage.setItem('asim_session', JSON.stringify(authenticated));
      setCurrentUser(authenticated);
      setActiveTab('dashboard');
      return true;
    }
    return false;
  };

  const handleUpdateSelf = (updated: User) => {
    localStorage.setItem('asim_session', JSON.stringify(updated));
    setCurrentUser(updated);
  };

  const handleLogout = () => {
    localStorage.removeItem('asim_session');
    setCurrentUser(null);
  };

  const handleNewOS = () => {
    setActiveTab('os');
    setIsCreatingOS(true);
  };

  const handleSaveOS = (data: any) => {
    api.createOS(data);
    alert("Ordem de Serviço salva com sucesso!");
    setIsCreatingOS(false);
  };

  if (!currentUser) {
    return <LoginView onLogin={handleLogin} />;
  }

  const renderContent = () => {
    if (currentUser.role === 'USER') {
      const restrictedTabs = ['caixa', 'fornecedores', 'configuracoes', 'usuarios', 'auditoria'];
      if (restrictedTabs.includes(activeTab)) {
        setActiveTab('dashboard');
        return <Dashboard onNewOS={handleNewOS} onViewAllOS={() => setActiveTab('os')} />;
      }
    }

    switch (activeTab) {
      case 'dashboard':
        return <Dashboard onNewOS={handleNewOS} onViewAllOS={() => setActiveTab('os')} />;
      case 'os':
        return isCreatingOS ? 
          <ServiceOrderForm onBack={() => setIsCreatingOS(false)} onSave={handleSaveOS} /> : 
          <ServiceOrdersList onNewOS={() => setIsCreatingOS(true)} />;
      case 'clientes':
        return <ClientsView />;
      case 'fornecedores':
        return <SuppliersView />;
      case 'lista-compras':
        return <ShoppingListView />;
      case 'estoque':
      case 'produtos':
        return <InventoryView />;
      case 'caixa':
        return <CashView />;
      case 'pre-orcamento':
        return <PreOrcamentoView />;
      case 'configuracoes':
        return <SettingsView />;
      case 'usuarios':
        return <UserManagementView currentUser={currentUser} onUpdateSelf={handleUpdateSelf} />;
      case 'auditoria':
        return <AuditLogsView />;
      default:
        return <Dashboard onNewOS={handleNewOS} onViewAllOS={() => setActiveTab('os')} />;
    }
  };

  return (
    <Layout 
      user={currentUser} 
      activeTab={activeTab} 
      setActiveTab={(tab) => {
        setActiveTab(tab);
        setIsCreatingOS(false);
      }}
    >
      {renderContent()}
    </Layout>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { MENU_ITEMS } from '../constants';
import { Menu, X, Bell, User as UserIcon, LogOut, Users as UsersIcon, History } from 'lucide-react';
import { User } from '../types';

interface LayoutProps {
  children: React.ReactNode;
  activeTab: string;
  setActiveTab: (tab: string) => void;
  user: User;
}

const Layout: React.FC<LayoutProps> = ({ children, activeTab, setActiveTab, user }) => {
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [config, setConfig] = useState({ logo: '', name: 'Painel da Asim' });

  useEffect(() => {
    const saved = localStorage.getItem('app_config');
    if (saved) setConfig(JSON.parse(saved));
  }, []);

  const handleLogout = () => {
    if (confirm("Deseja sair do sistema?")) {
      localStorage.removeItem('asim_session');
      window.location.reload();
    }
  };

  // Filtrar menu por papel
  const visibleMenuItems = MENU_ITEMS.filter(item => {
    if (user.role === 'USER') {
      return !['caixa', 'fornecedores', 'configuracoes'].includes(item.id);
    }
    return true;
  });

  return (
    <div className="min-h-screen flex flex-col md:flex-row overflow-hidden">
      <header className="md:hidden bg-white border-b px-4 py-3 flex items-center justify-between sticky top-0 z-50">
        <h1 className="text-xl font-bold text-blue-600">{config.name}</h1>
        <button onClick={() => setIsSidebarOpen(!isSidebarOpen)} className="p-2 hover:bg-slate-100 rounded-md">
          {isSidebarOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </header>

      {isSidebarOpen && <div className="fixed inset-0 bg-black/50 z-40 md:hidden" onClick={() => setIsSidebarOpen(false)} />}

      <aside className={`fixed md:relative top-0 bottom-0 left-0 w-64 bg-white border-r z-50 transform transition-transform duration-200 ease-in-out ${isSidebarOpen ? 'translate-x-0' : '-translate-x-full md:translate-x-0'} flex flex-col`}>
        <div className="p-8 hidden md:block border-b mb-4">
          {config.logo ? <img src={config.logo} alt="Logo" className="max-h-16 w-full object-contain" /> : <h1 className="text-2xl font-bold text-blue-600">{config.name}</h1>}
        </div>

        <nav className="flex-1 px-4 py-4 space-y-1 overflow-y-auto">
          {visibleMenuItems.map((item) => (
            <button key={item.id} onClick={() => { setActiveTab(item.id); setIsSidebarOpen(false); }} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-colors ${activeTab === item.id ? 'bg-blue-600 text-white shadow-md' : 'text-slate-600 hover:bg-slate-50'}`}>
              {item.icon} {item.label}
            </button>
          ))}

          {user.role === 'ADMIN' && (
            <>
              <div className="my-4 border-t border-slate-100 pt-4 px-4">
                <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-2">Administração</p>
              </div>
              <button onClick={() => { setActiveTab('usuarios'); setIsSidebarOpen(false); }} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-colors ${activeTab === 'usuarios' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-600 hover:bg-slate-50'}`}>
                <UsersIcon size={20} /> Equipe
              </button>
              <button onClick={() => { setActiveTab('auditoria'); setIsSidebarOpen(false); }} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-sm font-medium transition-colors ${activeTab === 'auditoria' ? 'bg-blue-600 text-white shadow-md' : 'text-slate-600 hover:bg-slate-50'}`}>
                <History size={20} /> Auditoria / Logs
              </button>
            </>
          )}
        </nav>

        <div className="p-4 border-t mt-auto space-y-2 bg-white">
          <div className="flex items-center gap-3 p-2 bg-slate-50 rounded-2xl border border-slate-100">
            <div className={`w-10 h-10 rounded-full flex items-center justify-center ${user.role === 'ADMIN' ? 'bg-blue-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
              <UserIcon size={18} />
            </div>
            <div className="flex-1 min-w-0">
              <p className="text-sm font-bold truncate">{user.name}</p>
              <p className="text-[9px] font-black uppercase text-blue-500 tracking-widest">{user.role === 'ADMIN' ? 'ADMINISTRADOR' : 'USUÁRIO'}</p>
            </div>
          </div>
          <button onClick={handleLogout} className="w-full flex items-center gap-3 px-4 py-2 text-rose-500 hover:bg-rose-50 rounded-xl text-xs font-black uppercase tracking-widest transition-all">
            <LogOut size={16} /> Sair do Painel
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto h-screen bg-slate-50/50">
        <div className="hidden md:flex bg-white border-b h-16 items-center justify-between px-8 sticky top-0 z-10">
          <h2 className="text-lg font-black text-slate-800 uppercase tracking-tight">
            {activeTab === 'usuarios' ? 'Equipe' : activeTab === 'auditoria' ? 'Auditoria' : MENU_ITEMS.find(item => item.id === activeTab)?.label}
          </h2>
          <div className="flex items-center gap-4">
            <button className="p-2 text-slate-500 hover:bg-slate-50 rounded-full relative"><Bell size={20} /></button>
            <div className="h-8 w-px bg-slate-200"></div>
            <span className="text-sm font-bold text-slate-400">{new Date().toLocaleDateString('pt-BR')}</span>
          </div>
        </div>
        <div className="p-4 md:p-8">{children}</div>
      </main>
    </div>
  );
};

