            </div>
            <form onSubmit={editingUser ? handleUpdate : handleAdd} className="p-10 space-y-6">
              <div className="space-y-4">
                <div>
                  <label className="text-[10px] font-black uppercase text-slate-400 mb-1 block">Nome do Colaborador</label>
