import { db } from '../firebase';
import { 
  collection, 
  addDoc, 
  getDocs, 
  updateDoc, 
  doc, 
  query, 
  where, 
  orderBy, 
  limit, 
  deleteDoc,
  Timestamp,
  getDoc
} from 'firebase/firestore';
import { Client, ServiceOrder, Product, CashTransaction, OSStatus, User, ActivityLog, CommissionReport } from '../types';

// Helpers de conversão de dados
const toData = (doc: any) => ({ id: doc.id, ...doc.data() });

const getCurrentUser = (): User | null => {
  const session = localStorage.getItem('asim_session');
  return session ? JSON.parse(session) : null;
};

// Sistema de Log em Nuvem
const registerLog = async (action: string, details: string, severity: ActivityLog['severity'] = 'info') => {
  const user = getCurrentUser();
  try {
    await addDoc(collection(db, 'logs'), {
      userId: user?.id || 'system',
      userName: user?.name || 'Sistema',
      action,
      details,
      severity,
      timestamp: new Date().toISOString()
    });
  } catch (e) {
    console.error("Erro ao registrar log no Firestore", e);
  }
};

export const api = {
  // --- AUDITORIA ---
  getLogs: async (): Promise<ActivityLog[]> => {
    const q = query(collection(db, 'logs'), orderBy('timestamp', 'desc'), limit(100));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(toData) as ActivityLog[];
  },

  // --- COMISSÕES ---
  getCommissions: async (startDate: string, endDate: string): Promise<CommissionReport[]> => {
    const usersSnap = await getDocs(collection(db, 'users'));
    const users = usersSnap.docs.map(toData) as User[];

    const osQuery = query(
      collection(db, 'os'), 
      where('status', '==', OSStatus.ENTREGUE)
    );
    const osSnap = await getDocs(osQuery);
    const deliveredOS = osSnap.docs.map(toData) as ServiceOrder[];

    // Filtro manual de data (Firestore queries em ranges compostos requerem índices manuais)
    const filteredOS = deliveredOS.filter(o => {
      const date = o.updatedAt.split('T')[0];
      return date >= startDate && date <= endDate;
    });

    return users.map(user => {
      const userOS = filteredOS.filter(o => o.responsibleId === user.id);
      const totalLabor = userOS.reduce((acc, o) => acc + o.financial.laborValue, 0);
      return {
        userId: user.id,
        userName: user.name,
        totalServices: totalLabor,
        totalValue: userOS.reduce((acc, o) => acc + o.financial.totalValue, 0),
        commissionValue: (totalLabor * (user.commissionRate || 0)) / 100,
        osCount: userOS.length
      };
    });
  },

  // --- USUÁRIOS E AUTH ---
  login: async (username: string, pass: string): Promise<User | null> => {
    const q = query(collection(db, 'users'), where('username', '==', username), where('password', '==', pass));
    const snapshot = await getDocs(q);
    if (!snapshot.empty) {
      const user = toData(snapshot.docs[0]) as User;
      registerLog('Login', `Usuário ${user.username} acessou o sistema`);
      return user;
    }
    return null;
  },

  getUsersList: async (): Promise<User[]> => {
    const snapshot = await getDocs(collection(db, 'users'));
    return snapshot.docs.map(toData) as User[];
  },

  addUser: async (userData: Omit<User, 'id' | 'createdAt'>): Promise<{success: boolean, message: string}> => {
    try {
      const newUser = {
        ...userData,
        createdAt: new Date().toISOString()
      };
      const docRef = await addDoc(collection(db, 'users'), newUser);
      registerLog('Criação de Usuário', `Novo usuário: ${userData.name}`, 'info');
      return { success: true, message: 'Usuário cadastrado!' };
    } catch (e) {
      return { success: false, message: 'Erro ao salvar no banco.' };
    }
  },

  updateUser: async (id: string, updates: Partial<User>): Promise<User> => {
    const docRef = doc(db, 'users', id);
    await updateDoc(docRef, updates);
    const updated = await getDoc(docRef);
    return toData(updated) as User;
  },

  removeUser: async (id: string): Promise<void> => {
    if (id === 'admin-1') return; // Proteção hardcoded
    await deleteDoc(doc(db, 'users', id));
    registerLog('Remoção de Usuário', `Acesso ID ${id} removido`, 'danger');
  },

  // --- ORDENS DE SERVIÇO ---
  getOS: async (): Promise<ServiceOrder[]> => {
    const q = query(collection(db, 'os'), orderBy('openedAt', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(toData) as ServiceOrder[];
  },

  createOS: async (osData: any): Promise<ServiceOrder> => {
    const user = getCurrentUser();
    // Obter contador para o número da OS
    const allOS = await getDocs(collection(db, 'os'));
    const osNumber = (allOS.size + 1001).toString();

    const newOS = {
      ...osData,
      osNumber,
      responsibleId: user?.id || 'system',
      responsibleName: user?.name || 'Sistema',
      openedAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      status: OSStatus.RECEBIDO
    };
    const docRef = await addDoc(collection(db, 'os'), newOS);
    registerLog('Nova OS', `OS #${osNumber} aberta para ${newOS.clientName}`, 'info');
    return { ...newOS, id: docRef.id };
  },

  updateOSStatus: async (id: string, newStatus: OSStatus): Promise<void> => {
    const docRef = doc(db, 'os', id);
    await updateDoc(docRef, { 
      status: newStatus,
      updatedAt: new Date().toISOString() 
    });
    registerLog('Status OS', `OS ID ${id} atualizada para ${newStatus}`, 'info');
  },

  // --- CLIENTES ---
  getClients: async (): Promise<Client[]> => {
    const snapshot = await getDocs(collection(db, 'clients'));
    return snapshot.docs.map(toData) as Client[];
  },
  saveClient: async (client: any) => {
    const newC = { ...client, createdAt: new Date().toISOString() };
    const docRef = await addDoc(collection(db, 'clients'), newC);
    registerLog('Novo Cliente', `Cadastro de ${client.name}`, 'info');
    return { ...newC, id: docRef.id };
  },

  // --- ESTOQUE ---
  getInventory: async (): Promise<Product[]> => {
    const snapshot = await getDocs(collection(db, 'products'));
    return snapshot.docs.map(toData) as Product[];
  },
  saveProduct: async (product: any) => {
    const newP = { 
      ...product, 
      createdAt: new Date().toISOString(), 
      lastSaleAt: new Date().toISOString(),
      active: true 
    };
    const docRef = await addDoc(collection(db, 'products'), newP);
    registerLog('Novo Produto', `Item ${product.name} adicionado`, 'info');
    return { ...newP, id: docRef.id };
  },
  getDeadStock: async (): Promise<Product[]> => {
    const sixtyDaysAgo = new Date();
    sixtyDaysAgo.setDate(sixtyDaysAgo.getDate() - 60);
    const snapshot = await getDocs(collection(db, 'products'));
    const products = snapshot.docs.map(toData) as Product[];
    return products.filter(p => p.lastSaleAt && new Date(p.lastSaleAt) < sixtyDaysAgo && p.quantity > 0);
  }
};

