import { db } from '../firebase';
import { 
  collection, 
  addDoc, 
  getDocs, 
  updateDoc, 
  doc, 
  query, 
  orderBy, 
  Timestamp,
  where
} from 'firebase/firestore';
import { ServiceOrder, OSStatus, User, ActivityLog, CommissionReport } from '../types';

// Helper para converter documentos do Firebase em objetos JS com ID
const toData = (doc: any) => ({ id: doc.id, ...doc.data() });

const getCurrentUser = (): User | null => {
  const session = localStorage.getItem('asim_session');
  return session ? JSON.parse(session) : null;
};

const registerLog = async (action: string, details: string, severity: ActivityLog['severity'] = 'info') => {
  const user = getCurrentUser();
  const newLog = {
    userId: user?.id || 'system',
    userName: user?.name || 'Sistema',
    action,
    details,
    severity,
    timestamp: new Date().toISOString()
  };
  try {
    await addDoc(collection(db, 'logs'), newLog);
  } catch (e) {
    console.warn("Falha ao registrar log no Firestore", e);
  }
};

export const api = {
  // --- LOGIN ---
  login: async (username: string, pass: string): Promise<User | null> => {
    // Para agilidade e segurança, mantemos o admin fixo ou buscamos em uma coleção 'users'
    if (username === 'admin' && pass === '123') {
      const user = { id: 'admin-1', name: 'Admin', username: 'admin', role: 'ADMIN', commissionRate: 0, createdAt: '' };
      registerLog('Login', `Usuário ${username} acessou o sistema`);
      return user as User;
    }
    return null;
  },

  // --- ORDENS DE SERVIÇO (Real Firestore) ---
  getOS: async (): Promise<ServiceOrder[]> => {
    try {
      const q = query(collection(db, 'ordensServico'), orderBy('openedAt', 'desc'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(toData) as ServiceOrder[];
    } catch (e) {
      console.error("Erro ao buscar OS:", e);
      return [];
    }
  },

  createOS: async (osData: any): Promise<ServiceOrder> => {
    const user = getCurrentUser();
    const osNumber = (Math.floor(1000 + Math.random() * 9000)).toString();

    const newOS = {
      ...osData,
      osNumber,
      responsibleId: user?.id || 'admin-1',
      responsibleName: user?.name || 'Administrador',
      openedAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
      status: OSStatus.RECEBIDO
    };

    try {
      const docRef = await addDoc(collection(db, 'ordensServico'), newOS);
      registerLog('Nova OS', `OS #${osNumber} aberta para ${osData.clientName}`);
      return { ...newOS, id: docRef.id };
    } catch (e) {
      console.error("Erro ao salvar OS no Firestore:", e);
      throw new Error("Erro de conexão com o banco de dados.");
    }
  },

  updateOSStatus: async (id: string, newStatus: OSStatus): Promise<void> => {
    try {
      const osRef = doc(db, 'ordensServico', id);
      await updateDoc(osRef, {
        status: newStatus,
        updatedAt: new Date().toISOString()
      });
      registerLog('Status OS', `OS ID ${id} atualizada para ${newStatus}`);
    } catch (e) {
      console.error("Erro ao atualizar status:", e);
    }
  },

  // --- CLIENTES ---
  getClients: async () => {
    const snapshot = await getDocs(collection(db, 'clientes'));
    return snapshot.docs.map(toData);
  },

  saveClient: async (client: any) => {
    const newC = { ...client, createdAt: new Date().toISOString() };
    const docRef = await addDoc(collection(db, 'clientes'), newC);
    return { ...newC, id: docRef.id };
  },

  // --- ESTOQUE ---
  getInventory: async () => {
    const snapshot = await getDocs(collection(db, 'produtos'));
    return snapshot.docs.map(toData);
  },

  getDeadStock: async () => {
    // Lógica de estoque parado agora via consulta Firestore
    const snapshot = await getDocs(collection(db, 'produtos'));
    const all = snapshot.docs.map(toData);
    const sixtyDaysAgo = new Date();
    sixtyDaysAgo.setDate(sixtyDaysAgo.getDate() - 60);
    return all.filter((p: any) => p.lastSaleAt && new Date(p.lastSaleAt) < sixtyDaysAgo && p.quantity > 0);
  },

  getLogs: async () => {
    const q = query(collection(db, 'logs'), orderBy('timestamp', 'desc'));
    const snapshot = await getDocs(q);
    return snapshot.docs.map(toData) as ActivityLog[];
  },

  getCommissions: async (start: string, end: string): Promise<CommissionReport[]> => {
    // No Firestore, o ideal é filtrar por data direto na query se o volume for alto
    const q = query(collection(db, 'ordensServico'), where('status', '==', OSStatus.ENTREGUE));
    const snapshot = await getDocs(q);
    const delivered = snapshot.docs.map(toData).filter((o: any) => {
      const date = o.updatedAt.split('T')[0];
      return date >= start && date <= end;
    });

    // Como os usuários ainda estão em localStorage/admin fixo, simulamos o agrupamento
    return [{
      userId: 'admin-1',
      userName: 'Administrador',
      totalServices: delivered.reduce((acc: number, o: any) => acc + (o.financial?.laborValue || 0), 0),
      totalValue: delivered.reduce((acc: number, o: any) => acc + (o.financial?.totalValue || 0), 0),
      commissionValue: 0,
      osCount: delivered.length
    }];
  },

  getUsersList: async () => [],
  addUser: async (userData: any) => ({ success: true, message: 'OK' }),
  updateUser: async (id: string, userData: any) => ({ ...userData, id }),
  removeUser: async (id: string) => ({ success: true })
};

