const USERS_COL = collection(db, "users");

// --- CLIENTES ---
export const getClients = async (): Promise<Client[]> => {
  const snapshot = await getDocs(CLIENTS_COL);
  return snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as Client));
};

