      username: 'admin',
      password: '123',
      name: 'Administrador',
      role: 'ADMIN',
      createdAt: new Date().toISOString()
    };
    await addDoc(USERS_COL, adminUser);
    return [adminUser as any];
  }
  return snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id } as User));
